insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3eedda97-43cc-433a-95d4-4bf4878958cd', 'fr', 'Elle est impliquée et l’énergie est forte. Quelle suite proposée comme une évidence garde l’élan ?', '["« On remet ça. Donne-moi ton numéro. »", "« Ça t’intéresserait qu’on se revoie ? »", "« Tu serais partante pour qu’on se voie un de ces jours ? »", "« Je me dis qu’on pourrait peut-être se voir ? »"]'::jsonb, 'Considère son intérêt comme acquis et propose directement le projet.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4051e636-695d-4534-936e-1f530668bf29', 'fr', 'Pourquoi trop de questions d’affilée déséquilibrent-elles la conversation ?', '["Elles lui laissent l’essentiel du travail", "On a l’impression que tu prends au lieu de partager", "Elles montrent que tu fais attention"]'::jsonb, 'Des questions qui s’enchaînent créent un déséquilibre où l’un donne et l’autre prend.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4533a8d2-717d-49b4-b4a9-c89b28985777', 'fr', 'Elle dit : « Je rentre d’un voyage au Japon. » Que pourrais-tu dire ensuite ?', '["Lui raconter tes propres voyages", "Demander : « Qu’est-ce que tu as préféré au Japon ? »", "Changer de sujet pour lui demander où elle habite", "La complimenter sur le fait qu’elle voyage"]'::jsonb, 'Rebondir sur son détail approfondit naturellement la conversation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48b2d089-1b51-4e26-9f2f-517c02891e1b', 'fr', 'Quels comportements montrent une implication non verbale ?', '["Être tourné vers elle quand elle parle", "Garder un visage neutre tout du long", "Un regard naturel", "De légers hochements de tête aux moments clés"]'::jsonb, 'L’orientation du corps, le regard et des réactions visibles montrent ta présence.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('497c00d6-116b-4bf7-9ccf-9fdbef04ef82', 'fr', 'Elle répond brièvement au sujet de sa famille, et l’énergie baisse. Que pourrais-tu faire ensuite ?', '["Poser une autre question sur sa famille", "Passer à autre chose avec légèreté : « Bref, ton plat, il est comment ? »", "T’excuser pour ce moment gênant", "Lui demander pourquoi elle a répondu si brièvement"]'::jsonb, 'Réoriente calmement vers un terrain neutre pour relancer l’élan sans pression.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4cd2af01-a10e-4c9e-b164-6c82a959ca1f', 'fr', 'Pourquoi insister pour avoir raison affaiblit-il le lien ?', '["Ça transforme la conversation en compétition", "Ça montre que tu fais passer le fait d’avoir raison avant le lien", "Ça montre ton intelligence sociale", "Ça lui donne l’impression d’avoir tort au lieu d’être simplement différente"]'::jsonb, 'Ce n’est pas le désaccord qui crée la tension, c’est le besoin d’avoir raison.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4d5ba9c1-712a-4d9d-b8a1-4ffec08ad96c', 'fr', 'Quel changement d’état d’esprit permet d’écouter pour comprendre ?', '["Préparer à l’avance des réponses astucieuses", "Être pleinement présent sans anticiper", "Te concentrer sur les points communs entre tes histoires et les siennes", "Réagir vite pour garder l’énergie"]'::jsonb, 'Être présent demande de lâcher les réponses préparées.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e01d376-3513-4958-b45f-3cbac7198e67', 'fr', 'Vous avez eu une super discussion sur son prochain voyage au Portugal. C’est le moment de partir. Que pourrais-tu dire ?', '["« Ravi d’avoir discuté avec toi, bonne journée. »", "« Le Portugal, ça a l’air génial. Il faudra que tu me racontes. »", "« Bon voyage, quand tu partiras. »"]'::jsonb, 'Termine par un rappel précis pour créer une continuité et une suite naturelle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e138ced-bcd3-4f4b-9394-d046b4bd81e7', 'fr', 'Elle parle d’essayer un café que tu lui as conseillé. Quelles façons de concrétiser mettent peu d’enjeu ?', '["« On devrait y aller ensemble cette semaine. Tu es libre samedi ? »", "« Je t’envoie l’adresse. C’est quoi, ton numéro ? »", "« Dis-moi si c’est bien quand tu iras »"]'::jsonb, 'Une demande sans pression fait baisser les défenses ; garde tes demandes petites pour que le oui soit naturel.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('52c57688-6476-42cc-9677-4cb5e66512fd', 'fr', 'Elle demande : « Pourquoi ta dernière relation s’est terminée ? » Quelle réponse est la plus posée ?', '["« Elle m’a fait beaucoup de mal, et je ne m’en suis pas encore remis. »", "« C’était toxique, et ça m’a vraiment détruit. »", "« On ne voulait pas les mêmes choses, et ça m’a appris ce qui compte le plus pour moi aujourd’hui. »"]'::jsonb, 'Cette réponse reconnaît la réalité tout en montrant du recul. Elle suscite la curiosité, pas l’inquiétude.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('535c49aa-9750-45dd-9796-69f61c22aedf', 'fr', 'Quels comportements montrent qu’on écoute pour répondre plutôt que pour comprendre ?', '["Lui refléter ce qu’elle a partagé", "Sauter vite aux conseils", "L’interrompre avant qu’elle ait fini", "Des réponses sans rapport avec ce qu’elle vient de dire"]'::jsonb, 'Ces comportements montrent une attention tournée vers la performance ou le contrôle plutôt que vers la compréhension.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('58d8c403-8e7d-4168-b8ba-758c4dff889c', 'fr', 'Elle dit : « Je rentre d’un voyage au Japon. » Que pourrais-tu dire ensuite ?', '["Lui raconter tes propres voyages", "Demander : « Qu’est-ce que tu as préféré au Japon ? »", "Changer de sujet pour lui demander où elle habite", "La complimenter sur le fait qu’elle voyage"]'::jsonb, 'Rebondir sur son détail approfondit naturellement la conversation.')
