insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59ddb591-0f25-456d-abef-ddcf1bc55c9f', 'fr', 'Elle raconte une mésaventure drôle en voyage. Que pourrait faire l’histoire que tu racontes en réponse ?', '["Lui répondre avec une anecdote drôle du même genre", "Raconter tout ton historique de voyages", "Sauter à un sujet complètement différent", "Donner un conseil au lieu de partager"]'::jsonb, 'Reste concis et structuré pour refléter son énergie et créer de la complicité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5def4588-2c49-4e7d-a78b-6de3a668455b', 'fr', 'Pourquoi trop de questions créent-elles un déséquilibre dans la conversation ?', '["Tu soutires des informations sans rien apporter en retour", "Les questions la poussent à performer et à te divertir", "Les deux réponses ci-dessus"]'::jsonb, 'Des questions qui s’enchaînent créent un déséquilibre où l’un donne et l’autre prend.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6309d2eb-7004-43f3-99ec-c276acb5ec61', 'fr', 'Elle soutient ton regard et pose des questions de relance. Qu’est-ce que ça indique ?', '["Elle est distraite et veut mettre fin à la discussion", "Il faut d’abord plus de conversation légère", "Elle est polie, mais pas intéressée", "Elle s’investit, et le moment est venu de concrétiser"]'::jsonb, 'Une curiosité active et un langage corporel positif montrent que le moment est venu de concrétiser.')
