insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66cbe1b3-1585-4d3f-b00f-bb1fcf3143d3', 'fr', 'Que se passe-t-il quand tu passes à autre chose sans reconnaître ce qu’elle a dit ?', '["Tu as l’air pressé", "Ça laisse penser que tu n’as peut-être pas compris son message", "Ça réduit les sujets de conversation", "Ça ralentit l’élan"]'::jsonb, 'La reconnaissance montre que tu as compris ; ajoute-la avant de poser la question suivante.')
