insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('674acf71-26d4-428e-aa33-571e27f0d7d7', 'fr', 'Qu’est-ce qui rend le fait de rebondir sur un fil plus naturel que de sauter d’un sujet à l’autre ?', '["C’est comme ça que les amis se parlent vraiment", "La conversation se construit au lieu de paraître décousue", "Elle se sent écoutée parce que tu réponds à ce qu’elle dit", "La conversation se construit, et elle se sent écoutée"]'::jsonb, 'Rebondir sur les fils crée de la fluidité ; chaque réponse s’appuie sur la précédente.')
