insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('68abae72-376e-4c38-bd5f-a63ad5d4ed56', 'fr', 'Elle raconte brièvement une échéance stressante au travail qu’elle vient de tenir. Ta réponse ?', '["Reconnaître ce qu’elle a vécu, puis raconter un défi semblable que tu as relevé au travail", "Lui donner tout de suite des conseils de carrière", "Passer à tes projets pour le week-end"]'::jsonb, 'Accorde-toi à son énergie avec une histoire courte et pertinente pour créer de la complicité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6a3257d1-17bb-4df3-b9ca-c907755b7988', 'fr', 'Qu’est-ce qui fait une bonne histoire en début de conversation ?', '["Choisir un moment précis avec un impact émotionnel", "Mettre le plus de détails possible", "Raconter les faits exactement comme tu t’en souviens", "La faire longue pour montrer de la profondeur"]'::jsonb, 'Un instantané resserré sur ce qui a compté crée du lien plus vite qu’un historique complet.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('72a6b099-3278-4a37-8a82-51225280d333', 'fr', 'Qu’est-ce qui crée des ancrages émotionnels positifs ?', '["Un vrai rire, pas poli, une vraie joie", "La reconnaissance de ce qui compte pour elle", "La curiosité, qui l’amène à se voir autrement", "Toutes les réponses ci-dessus"]'::jsonb, 'La reconnaissance, la curiosité et le rire font avancer les émotions.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('75148042-557e-4fcd-b9cf-a733e31a8702', 'fr', 'Elle dit : « Je viens de rendre visite à ma sœur à Portland. » Que pourrais-tu dire ensuite ?', '["« Tu voyages beaucoup ? »", "« C’est chouette que tu sois proche de ta sœur. Vous avez fait quoi ? »", "« Portland, c’est génial. Tu es déjà allée à Seattle ? »", "« Le voyage a duré combien de temps ? »"]'::jsonb, 'Reconnais d’abord ce qu’elle a vécu pour montrer que tu comprends, avant d’aller plus loin.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('75dbf155-f762-4c46-a881-ee4691d19f29', 'fr', 'Quel état d’esprit permet le mieux de concrétiser, de manière générale ?', '["« Il faut que j’obtienne quelque chose »", "« Il faut que ça aboutisse »", "« C’est maintenant ou jamais »", "« Avançons d’un petit pas »"]'::jsonb, 'Les petits pas font baisser les défenses ; garde tes demandes petites pour que le oui soit naturel.')
