insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8105c1a4-951f-4041-9374-fb7c65a70dca', 'fr', 'Quels fils t’offre « Je suis avocate » ?', '["Son rôle précis et ses responsabilités", "Le domaine du droit dans lequel elle exerce", "Son expérience et son parcours professionnel", "Toutes les réponses ci-dessus"]'::jsonb, 'Rebondir sur un fil, c’est approfondir son sujet ; pose des questions précises sur ce qu’elle a mentionné.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8389bf63-7797-4fed-8bf2-0f7cb7b996c7', 'fr', 'La conversation coule bien et elle rit. Que pourrais-tu dire pour proposer la suite comme une évidence ?', '["« Ça te dirait peut-être d’aller boire un café un de ces jours ? »", "« Je ne sais pas, mais on pourrait peut-être se voir ? »", "« Tu veux qu’on échange nos numéros ? »", "« Allons boire un café. C’est quoi, ton numéro ? »"]'::jsonb, 'Énonce la suite avec assurance, comme un fait, au lieu de demander la permission.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8424db00-09f4-4aa8-b16b-d90b7a683c0b', 'fr', 'Pourquoi les longs monologues réduisent-ils l’attirance ?', '["Ils sonnent récités", "Ils lui enlèvent l’occasion de s’investir", "Ils ralentissent la conversation", "Ils en révèlent trop"]'::jsonb, 'Quand elle ne peut pas participer, son investissement baisse. Laisse-lui de la place pour partager.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8578c723-b332-450d-8dd1-4eaad1b6150b', 'fr', 'Pourquoi relier ton histoire à son univers à elle ?', '["Ça crée un vrai échange au lieu de deux histoires parallèles", "Ça montre que tu te sers de l’histoire pour la comprendre", "Ça évite que la conversation paraisse cloisonnée", "Toutes les réponses ci-dessus"]'::jsonb, 'Relier fait de l’histoire un outil de lien, pas seulement une performance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('87339858-15ab-4a2b-89af-d6a42cafac7a', 'fr', 'À quoi servent les phrases de reconnaissance ?', '["Montrer que ses mots t’ont vraiment touché", "Faire de la place pour un échange plus sincère", "Montrer de l’assurance et de la sensibilité émotionnelle", "La garder ancrée dans le moment, avec le sentiment d’être comprise"]'::jsonb, 'Reconnaître ses mots montre que tu les as entendus, ce qui l’invite à se confier davantage.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97b34e22-5615-4aa3-bf23-73f5718f67c6', 'fr', 'Quelles façons de faire transforment une histoire en lien plutôt qu’en impasse ?', '["Finir en soulignant à quel point le résultat était impressionnant", "Lui demander ce que la situation lui évoque", "Rattacher l’histoire à quelque chose qu’elle a déjà mentionné"]'::jsonb, 'Les histoires créent du lien quand elles invitent son univers dans la conversation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97e7b932-511e-48e1-bf8b-9b0e49bd18f9', 'fr', 'Elle parle, et tu te rends compte que tu prépares ta réponse. Que dois-tu faire ?', '["Finir vite de préparer, puis te reconcentrer sur ce qu’elle dit", "Arrêter de préparer et reporter tout de suite ton attention sur ses mots", "Lui demander de répéter la fin, puisque tu as décroché"]'::jsonb, 'Remarque que tu décroches, puis ramène immédiatement ton attention sur ses mots et son ton.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('998825a4-01bc-40bc-9219-b9e8a227feb8', 'fr', 'Tu sens une tension après avoir donné un avis différent. Quelle est la façon la plus propre de rebondir ?', '["Adoucir ton ton et lui demander ce qu’elle en a vécu", "En remettre une couche avec plus d’arguments", "T’excuser de ne pas être d’accord"]'::jsonb, 'Passe de prouver à comprendre ; invite plutôt son expérience.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a3ada69-efcb-4e14-96d0-7d4c087e2d2a', 'fr', 'Qu’apportent surtout les observations et les affirmations à une conversation ?', '["Elles équilibrent l’échange", "Elles révèlent ton propre point de vue", "Elles l’obligent à répondre"]'::jsonb, 'Elles rendent l’échange partagé et chaleureux.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9b82f398-1878-449a-baf9-24e1e9ec6c0d', 'fr', 'Pourquoi partager une expérience digérée crée-t-il du lien ?', '["Ça montre de la lucidité sur toi et de l’évolution", "Ça révèle une vulnérabilité sans lui faire porter un poids émotionnel", "Ça invite à la proximité sans l’obliger à t’aider", "Toutes les réponses ci-dessus"]'::jsonb, 'Quand une expérience est digérée, elle invite au lien plutôt qu’à prendre soin de toi.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9bb0ed54-392a-4aab-9aed-715508c1df96', 'fr', 'Tu n’es pas d’accord avec son avis sur un film. Elle a l’air passionnée. Que pourrais-tu faire ensuite ?', '["Expliquer pourquoi son avis ne tient pas", "Dire : « J’aime bien ton point de vue. Pourquoi tu l’adores autant ? »", "Faire semblant d’être d’accord pour que ça reste fluide", "Passer tout de suite à un autre sujet"]'::jsonb, 'Montre de la curiosité pour sa passion pour rester connectés malgré vos différences.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9d4b7485-9598-45ab-9df1-95a6de8dbd91', 'fr', 'Elle dit : « J’ai fini tard tous les soirs cette semaine. » Que pourrais-tu dire ensuite ?', '["« Tu fais quoi comme travail ? »", "« Tu as clairement mérité une soirée de sortie. »", "« Tu travailles combien d’heures ? »", "« Tu es fatiguée ? »"]'::jsonb, 'Une affirmation apporte quelque chose et l’invite à partager sans pression.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f096c93-c6af-4940-a92a-503d7c7f4a16', 'fr', 'Elle dit qu’elle a du mal dans son nouveau travail. Tu partages ta propre expérience. Et ensuite ?', '["« J’ai vécu la même chose. Bref… »", "« Et toi, comment tu gères l’adaptation pour l’instant ? »", "« Tu fais quoi exactement ? »"]'::jsonb, 'Relie-toi à sa situation actuelle pour inviter son point de vue et renforcer la complicité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f811f6d-ea33-440c-a2f7-4e4f2eab4134', 'fr', 'Elle dit qu’elle est stressée par le travail. Quelle réponse crée une association positive ?', '["« Ça a l’air dur. Le travail, c’est brutal. »", "« Tu devrais mieux gérer ton temps. »", "« Tout le monde est stressé en ce moment. »", "« Qu’est-ce que tu as le plus hâte de faire une fois que ce sera fini ? »"]'::jsonb, 'Ça fait passer doucement son état émotionnel du stress au soulagement et à l’impatience.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a3852cf6-c43a-47f6-95c6-432c2afa408f', 'fr', 'Vous marchez ensemble, et la conversation ralentit. Qu’est-ce qui signale une relance propre ?', '["Une pause détendue avant de réorienter", "Changer de sujet à toute vitesse", "Lui demander si elle s’ennuie"]'::jsonb, 'Le calme transmet plus d’assurance que la vitesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
